import requests
import json





def get_strikeout_prop(long_list=[]):

    if long_list == []:

        # Your Sportradar API key
        API_KEY = 'xXrWTGWlR1iF4l4JH0Vw3eIN7jZzCc6aA2bu1NKN'

        # Endpoint variables
        locale = 'en'
        urn_sport = 'sr:sport:3' 
        urn_date = '2025-05-26'   # Replace with your desired date

        # Construct the endpoint URL
        base_url = 'https://api.sportradar.com/oddscomparison-player-props/trial/v2'
        endpoint = f'/{locale}/sports/{urn_sport}/schedules/{urn_date}/players_props.json'

        # Full request URL
        url = base_url + endpoint

        # Send the request
        response = requests.get(url, params={'api_key': API_KEY})

        # Handle the response
        if response.status_code == 200:
            data = response.json()
            # print(data)  # or handle the JSON data as needed
        else:
            print(f'Error: {response.status_code} - {response.text}')
        
        player_props = data['sport_schedule_sport_events_players_props']
        player_props = player_props[0]
        player_props = player_props['players_props']
        player_props = player_props[0] # Gets to to the list of either game props or player props
        player_props = player_props['markets'] # might get to the list of all props in the market
        # player_props = player_props['sport_event']
    
    else:
        player_props = long_list



    # print(f"data: {data}")
    print(f"player_props: {player_props}, len: {len(player_props)}")
    print(f"player_props type: {type(player_props)}")
    print(f"\n List of dictioraries of different props\n")
    for prop in player_props:
        print(f"Prop info:")
        print(f"{prop}\n")
    # print(f"sport_event: {sport_event}. len: {len(sport_event)}")

    return




